<?php
header_page('Manage exhibits',$u);
function form_start(string $action): void { echo '<form method="post">'.csrf_field().'<input type="hidden" name="action" value="'.esc($action).'">'; }
function field(string $label,string $name,string $type='text',string $value=''): void { echo '<label>'.esc($label).'<input type="'.esc($type).'" name="'.esc($name).'" value="'.esc($value).'" maxlength="254" required></label>'; }
function pick(string $label,string $name,array $rows,string $key='name'): void { echo '<label>'.esc($label).'<select name="'.esc($name).'" required>'; foreach ($rows as $r) echo '<option value="'.(int)$r['id'].'">'.esc($r[$key]).'</option>'; echo '</select></label>'; }
function form_end(string $label='Save'): void {echo '<button>'.esc($label).'</button></form>';}
$museums=q('SELECT * FROM zp_museums ORDER BY name')->fetchAll();
$locations=q('SELECT l.*,CONCAT(m.name," / ",l.name) label FROM zp_locations l JOIN zp_museums m ON m.id=l.museum_id ORDER BY label')->fetchAll();
$exhibits=q('SELECT e.*,CONCAT(m.name," / ",l.name," / ",e.name) label FROM zp_exhibits e JOIN zp_locations l ON l.id=e.location_id JOIN zp_museums m ON m.id=l.museum_id ORDER BY label')->fetchAll();
$staff=q("SELECT * FROM zp_users WHERE role='staff' ORDER BY name")->fetchAll();
$devices=q('SELECT c.*,CONCAT(e.name," / ",c.name,IF(c.active=1,""," (retired)")) label FROM zp_components c JOIN zp_exhibits e ON e.id=c.exhibit_id ORDER BY label')->fetchAll();
echo '<h1>Manage your fleet</h1><p class="muted">Register exhibits, connect components, and assign individual access.</p>';
if ($notice) echo '<p class="alert">'.esc($notice).'</p>';
if ($generated) echo '<section class="panel"><h2>Save this link</h2><p>Shown once. Account links expire in one hour. Viewing links remain valid until revoked. Anyone with a viewing link can access its high-level information.</p><pre>'.esc($generated).'</pre></section>';
render_remote_access_admin($devices);
echo '<div class="columns"><section class="panel"><h2>Add a museum</h2>'; form_start('museum');field('Museum / client name','name');form_end('Add museum'); echo '</section>';
echo '<section class="panel"><h2>Add a location</h2>';form_start('location');pick('Museum','museum_id',$museums);field('Gallery / location name','name');field('Timezone','timezone','text','America/Chicago');form_end('Add location');echo '</section>';
echo '<section class="panel"><h2>Add an exhibit</h2>';form_start('exhibit');pick('Location','location_id',$locations,'label');field('Exhibit name','name');form_end('Add exhibit');echo '</section>';
echo '<section class="panel"><h2>Connect a component</h2><p>Create one identity per reporting Pi. Sensors can report through that Pi as named metrics.</p>';form_start('component');pick('Exhibit','exhibit_id',$exhibits,'label');field('Component name','name');form_end('Generate setup configuration');echo '</section>';
echo '<section class="panel"><h2>Invite a staff member</h2>';form_start('invite');field('Name','name');field('Email','email','email');form_end('Create account and access link');echo '<p class="muted">'.(cfg()['mail_enabled']?'Email delivery is configured; verify receipt.':'Email is not configured. Deliver the one-hour link privately yourself.').'</p></section>';
echo '<section class="panel"><h2>Assign exhibit access</h2>';form_start('permission');pick('Staff member','user_id',$staff);pick('Exhibit','exhibit_id',$exhibits,'label');
echo '<p>Basic viewing is included. Saving replaces this person’s permissions for the selected exhibit.</p><label><input type="checkbox" name="detail"> Detailed logs and metrics</label><label><input type="checkbox" name="control"> Approved remote controls (reserved; unavailable in this release)</label><label><input type="checkbox" name="manage"> Exhibit management (reserved for future maintenance functions)</label><label><input type="checkbox" name="point"> Make primary point person</label>';form_end('Assign access');echo '</section>';
echo '<section class="panel"><h2>Share an exhibit</h2>';form_start('share');echo '<input type="hidden" name="scope" value="exhibit">';pick('Exhibit','scope_id',$exhibits,'label');field('Link label','label');form_end('Create viewing link');echo '</section>';
echo '<section class="panel"><h2>Share a location</h2>';form_start('share');echo '<input type="hidden" name="scope" value="location">';pick('Location','scope_id',$locations,'label');field('Link label','label');form_end('Create viewing link');echo '</section>';
echo '<section class="panel"><h2>Move an exhibit</h2><p>This clears staff assignments and the point person, and revokes exhibit links. Reassign access after moving so the former team does not retain access.</p>';form_start('move');pick('Exhibit','exhibit_id',$exhibits,'label');pick('New location','location_id',$locations,'label');form_end('Move and clear access');echo '</section>';
echo '<section class="panel"><h2>Replace a component</h2><p>Register the replacement first. Old logs stay attached; the retired device can no longer upload.</p>';form_start('replace');pick('Old component','old_id',$devices,'label');pick('Replacement','new_id',array_values(array_filter($devices,fn($d)=>(bool)$d['active'])),'label');form_end('Record replacement');echo '</section></div>';
echo '<section class="panel"><h2>Staff accounts</h2><div class="table-wrap"><table><tr><th>Person</th><th>Email</th><th>Access</th><th>Actions</th></tr>';
foreach ($staff as $s) {echo '<tr><td>'.esc($s['name']).'</td><td>'.esc($s['email']).'</td><td>'.($s['active']?'Enabled':'Disabled').'</td><td>';form_start('user-active');echo '<input type="hidden" name="user_id" value="'.(int)$s['id'].'">';form_end($s['active']?'Disable':'Enable');if ($s['active']) {form_start('access-link');echo '<input type="hidden" name="user_id" value="'.(int)$s['id'].'">';form_end('New password / invitation link');}echo '</td></tr>';}
echo '</table></div></section><section class="panel"><h2>Current exhibit assignments</h2><div class="table-wrap"><table><tr><th>Staff</th><th>Exhibit</th><th>Permissions</th><th></th></tr>';
foreach (q('SELECT p.*,u.name person,e.name exhibit FROM zp_permissions p JOIN zp_users u ON u.id=p.user_id JOIN zp_exhibits e ON e.id=p.exhibit_id ORDER BY u.name,e.name') as $p) {echo '<tr><td>'.esc($p['person']).'</td><td>'.esc($p['exhibit']).'</td><td>View'.($p['detail']?', detailed logs':'').($p['control']?', control reserved':'').($p['manage']?', management reserved':'').'</td><td>';form_start('permission');echo '<input type="hidden" name="user_id" value="'.(int)$p['user_id'].'"><input type="hidden" name="exhibit_id" value="'.(int)$p['exhibit_id'].'"><input type="hidden" name="remove" value="1">';form_end('Remove access');echo '</td></tr>';}
echo '</table></div></section><section class="panel"><h2>Viewing links</h2><table><tr><th>Label</th><th>Scope</th><th></th></tr>';
foreach (q('SELECT s.*,e.name exhibit,l.name location FROM zp_shares s LEFT JOIN zp_exhibits e ON e.id=s.exhibit_id LEFT JOIN zp_locations l ON l.id=s.location_id WHERE s.active=1 ORDER BY s.id DESC') as $s) {echo '<tr><td>'.esc($s['label']).'</td><td>'.esc($s['exhibit'] ?? $s['location']).'</td><td>'; $view=exhibit_share_url($s);if($view)echo '<p><a href="'.esc($view).'">Open viewing link</a><br><code>'.esc($view).'</code></p>';else echo '<p>Existing link preserved. Use your saved URL.</p>';form_start('revoke-share');echo '<input type="hidden" name="share_id" value="'.(int)$s['id'].'">';form_end('Revoke');echo '</td></tr>';}
echo '</table></section><section class="panel"><h2>Components</h2><table><tr><th>Component</th><th>Device</th><th></th></tr>';
foreach ($devices as $d) {echo '<tr><td>'.esc($d['label']).'</td><td>'.esc($d['device_id']).'</td><td>';if ($d['active']) {form_start('retire');echo '<input type="hidden" name="component_id" value="'.(int)$d['id'].'">';form_end('Retire device');}echo '</td></tr>';}
echo '</table></section><section class="panel"><h2>Administrator activity</h2><table><tr><th>UTC time</th><th>Action</th><th>Details</th></tr>';
foreach (q('SELECT created_at,action,details FROM zp_audit ORDER BY id DESC LIMIT 50') as $r) echo '<tr><td>'.esc($r['created_at']).'</td><td>'.esc($r['action']).'</td><td>'.esc($r['details']).'</td></tr>';
echo '</table></section>';footer_page();
